'use client';

import React, { forwardRef, useRef } from 'react';
import { AnimatedBeam } from '~/components/ui/animated-beam';
import { GridPattern } from '~/components/ui/grid-pattern';
import { cn } from '@acme/ui';

const Circle = forwardRef<HTMLDivElement, { className?: string; children?: React.ReactNode }>(({ className, children }, ref) => {
  return (
    <div
      ref={ref}
      className={cn(
        'z-10 flex size-12 items-center justify-center rounded-full border-2 bg-white p-3 shadow-[0_0_20px_-12px_rgba(0,0,0,0.8)]',
        className
      )}
    >
      {children}
    </div>
  );
});

Circle.displayName = 'Circle';

export function HeroCard() {
  const containerRef = useRef<HTMLDivElement>(null);

  const usr1Ref = useRef<HTMLDivElement>(null);
  const usr2Ref = useRef<HTMLDivElement>(null);
  const usr3Ref = useRef<HTMLDivElement>(null);

  const chainRef = useRef<HTMLDivElement>(null);
  const oracleRef = useRef<HTMLDivElement>(null);

  const bank1Ref = useRef<HTMLDivElement>(null);
  const bank2Ref = useRef<HTMLDivElement>(null);
  const bank3Ref = useRef<HTMLDivElement>(null);

  return (
    <div className="relative  flex h-[300px] w-full overflow-visible items-center justify-center p-10" ref={containerRef}>
      <GridPattern
        className={cn(
          '[mask-image:radial-gradient(400px_circle_at_center,white,transparent)]',
          ' -inset-x-[15%] inset-y-[-35%] h-[200%]  w-[130%]   skew-y-18'
        )}
      />

      <div className="flex size-full max-h-[200px] max-w-lg flex-col items-stretch justify-between gap-10">
        <div className="flex flex-row items-center justify-between">
          <Circle ref={usr1Ref}>
            <Icons.user />
          </Circle>

          <Circle ref={bank1Ref}>
            <Icons.bank />
          </Circle>
        </div>

        <div className="flex flex-row items-center justify-between">
          <Circle ref={usr2Ref}>
            <Icons.user />
          </Circle>

          <Circle ref={chainRef} className="size-16">
            <Icons.blockchain />
          </Circle>
          <Circle ref={oracleRef} className="size-16">
            <Icons.oracle />
          </Circle>

          <Circle ref={bank2Ref}>
            <Icons.bank />
          </Circle>
        </div>

        <div className="flex flex-row items-center justify-between">
          <Circle ref={usr3Ref}>
            <Icons.user />
          </Circle>
          <Circle ref={bank3Ref}>
            <Icons.bank />
          </Circle>
        </div>
      </div>

      <AnimatedBeam containerRef={containerRef} fromRef={chainRef} toRef={oracleRef} />

      <AnimatedBeam containerRef={containerRef} fromRef={bank1Ref} toRef={oracleRef} />
      <AnimatedBeam containerRef={containerRef} fromRef={bank1Ref} toRef={oracleRef} reverse />

      <AnimatedBeam containerRef={containerRef} fromRef={bank2Ref} toRef={oracleRef} />
      <AnimatedBeam containerRef={containerRef} fromRef={bank2Ref} toRef={oracleRef} reverse />

      <AnimatedBeam containerRef={containerRef} fromRef={bank3Ref} toRef={oracleRef} />
      <AnimatedBeam containerRef={containerRef} fromRef={bank3Ref} toRef={oracleRef} reverse />

      <AnimatedBeam containerRef={containerRef} fromRef={usr1Ref} toRef={chainRef} />
      <AnimatedBeam containerRef={containerRef} fromRef={usr2Ref} toRef={chainRef} />
      <AnimatedBeam containerRef={containerRef} fromRef={usr3Ref} toRef={chainRef} />
    </div>
  );
}

